import * as React from "react";
import { PaletteRoot, type PaletteColor } from "@/components/bevelui/palette";

export function ThemeEditor() {
  const [colors, setColors] = React.useState<PaletteColor[]>([
    { id: "brand", hex: "#c2f13c", name: "Brand" },
  ]);

  return (
    <PaletteRoot
      colors={colors}
      onChange={setColors}
      config={{ maxColors: 12 }}
    />
  );
}

