import {
  PaletteRoot,
  PaletteGrid,
  PaletteColorEditor,
  PaletteToolbar,
} from "@/components/bevelui/palette";

export function SideBySidePalette() {
  return (
    <PaletteRoot defaultColors={[]}>
      <div className="flex flex-col gap-3">
        <PaletteToolbar />
        <div className="flex gap-4 items-start">
          <PaletteGrid className="flex-1" />
          <PaletteColorEditor />
        </div>
      </div>
    </PaletteRoot>
  );
}

import { PaletteRoot, PaletteGrid, usePalette } from "@/components/bevelui/palette";

function PaletteActions() {
  const { colors, selectedId, add, remove, duplicate } = usePalette();

  return (
    <div className="flex items-center gap-2">
      <span className="text-xs text-muted-foreground">{colors.length} colors</span>
      <button onClick={() => add("#6366f1")}>Add indigo</button>
      {selectedId && (
        <>
          <button onClick={() => duplicate(selectedId)}>Duplicate</button>
          <button onClick={() => remove(selectedId)}>Delete</button>
        </>
      )}
    </div>
  );
}

// usePalette must be called inside PaletteRoot
export function App() {
  return (
    <PaletteRoot defaultColors={[]}>
      <PaletteGrid />
      <PaletteActions />
    </PaletteRoot>
  );
}
